1	//! Processes incoming hook calls from AI agents and rewrites commands on the fly.
2	//!
3	//! Uses `writeln!(stdout, ...)` instead of `println!` — accidental stdout/stderr
4	//! corrupts the JSON protocol (Claude Code bug #4669 silently disables the hook).
5	
6	use super::constants::PRE_TOOL_USE_KEY;
7	use super::permissions::{self, PermissionVerdict};
8	use anyhow::{Context, Result};
9	use serde_json::{json, Value};
10	use std::io::{self, Read, Write};
11	
12	use crate::discover::registry::{has_heredoc, rewrite_command};
13	
14	const STDIN_CAP: usize = 1_048_576; // 1 MiB
15	
16	fn read_stdin_limited() -> Result<String> {
17	    let mut input = String::new();
18	    io::stdin()
19	        .take((STDIN_CAP + 1) as u64)
20	        .read_to_string(&mut input)
21	        .context("Failed to read stdin")?;
22	    if input.len() > STDIN_CAP {
23	        anyhow::bail!("hook stdin exceeds {} byte limit", STDIN_CAP);
24	    }
25	    Ok(input)
26	}
27	
28	// ── Copilot hook (VS Code + Copilot CLI) ──────────────────────
29	
30	/// Format detected from the preToolUse JSON input.
31	enum HookFormat {
32	    /// VS Code Copilot Chat / Claude Code: `tool_name` + `tool_input.command`, supports `updatedInput`.
33	    VsCode { command: String },
34	    /// GitHub Copilot CLI: camelCase `toolName` + `toolArgs` (JSON string), supports `modifiedArgs` for transparent rewrite.
35	    /// Carries the full parsed `toolArgs` object so we can rewrite `command` while preserving
36	    /// host-supplied metadata (description, initial_wait, mode, …) the tool requires.
37	    CopilotCli { command: String, args: Value },
38	    /// Non-bash tool, already uses rtk, or unknown format — pass through silently.
39	    PassThrough,
40	}
41	
42	/// Run the Copilot preToolUse hook.
43	/// Auto-detects VS Code Copilot Chat vs Copilot CLI format.
44	pub fn run_copilot() -> Result<()> {
45	    let input = read_stdin_limited()?;
46	
47	    // Strip leading BOM(s) before trimming: some Windows hosts prepend UTF-8
48	    // BOMs to hook stdin (confirmed for Cursor), which serde_json rejects.
49	    let input = strip_leading_bom(&input).trim();
50	    if input.is_empty() {
51	        return Ok(());
52	    }
53	
54	    let v: Value = match serde_json::from_str(input) {
55	        Ok(v) => v,
56	        Err(e) => {
57	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
58	            return Ok(());
59	        }
60	    };
61	
62	    match detect_format(&v) {
63	        HookFormat::VsCode { command } => handle_vscode(&command),
64	        HookFormat::CopilotCli { command, args } => handle_copilot_cli(&command, &args),
65	        HookFormat::PassThrough => Ok(()),
66	    }
67	}
68	
69	fn detect_format(v: &Value) -> HookFormat {
70	    // VS Code Copilot Chat / Claude Code: snake_case keys
71	    if let Some(tool_name) = v.get("tool_name").and_then(|t| t.as_str()) {
72	        if matches!(tool_name, "runTerminalCommand" | "Bash" | "bash") {
73	            if let Some(cmd) = v
74	                .pointer("/tool_input/command")
75	                .and_then(|c| c.as_str())
76	                .filter(|c| !c.is_empty())
77	            {
78	                return HookFormat::VsCode {
79	                    command: cmd.to_string(),
80	                };
81	            }
82	        }
83	        return HookFormat::PassThrough;
84	    }
85	
86	    // Copilot CLI: camelCase keys, toolArgs is a JSON-encoded string
87	    if let Some(tool_name) = v.get("toolName").and_then(|t| t.as_str()) {
88	        if tool_name == "bash" {
89	            if let Some(tool_args_str) = v.get("toolArgs").and_then(|t| t.as_str()) {
90	                if let Ok(tool_args) = serde_json::from_str::<Value>(tool_args_str) {
91	                    if let Some(cmd) = tool_args
92	                        .get("command")
93	                        .and_then(|c| c.as_str())
94	                        .filter(|c| !c.is_empty())
95	                    {
96	                        return HookFormat::CopilotCli {
97	                            command: cmd.to_string(),
98	                            args: tool_args,
99	                        };
100	                    }

100	                    }
101	                }
102	            }
103	        }
104	        return HookFormat::PassThrough;
105	    }
106	
107	    HookFormat::PassThrough
108	}
109	
110	fn get_rewritten(cmd: &str) -> Option<String> {
111	    if has_heredoc(cmd) {
112	        return None;
113	    }
114	
115	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
116	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
117	        .unwrap_or_default();
118	
119	    let rewritten = rewrite_command(cmd, &excluded, &transparent_prefixes)?;
120	
121	    if rewritten == cmd {
122	        return None;
123	    }
124	
125	    Some(rewritten)
126	}
