128	fn handle_vscode(cmd: &str) -> Result<()> {
129	    let verdict = permissions::check_command(cmd);
130	    if verdict == PermissionVerdict::Deny {
131	        audit_log("deny", cmd, "");
132	        return Ok(());
133	    }
134	
135	    let rewritten = match get_rewritten(cmd) {
136	        Some(r) => r,
137	        None => return Ok(()),
138	    };
139	
140	    // Allow (explicit rule matched): auto-allow the rewritten command.
141	    // Ask/Default (no allow rule matched): rewrite but let the host tool prompt.
142	    let decision = match verdict {
143	        PermissionVerdict::Allow => "allow",
144	        _ => "ask",
145	    };
146	
147	    audit_log("rewrite", cmd, &rewritten);
148	
149	    let output = json!({
150	        "hookSpecificOutput": {
151	            "hookEventName": PRE_TOOL_USE_KEY,
152	            "permissionDecision": decision,
153	            "permissionDecisionReason": "RTK auto-rewrite",
154	            "updatedInput": { "command": rewritten }
155	        }
156	    });
157	    let _ = writeln!(io::stdout(), "{output}");
158	    Ok(())
159	}
