161	fn handle_copilot_cli(cmd: &str, args: &Value) -> Result<()> {
162	    if let Some(response) = copilot_cli_response(cmd, args) {
163	        let _ = writeln!(io::stdout(), "{response}");
164	    }
165	    Ok(())
166	}
