168	fn copilot_cli_response(cmd: &str, args: &Value) -> Option<Value> {
169	    copilot_cli_response_for_verdict(cmd, args, permissions::check_command(cmd))
170	}
171	
172	fn copilot_cli_response_for_verdict(
173	    cmd: &str,
174	    args: &Value,
175	    verdict: PermissionVerdict,
176	) -> Option<Value> {
177	    if verdict == PermissionVerdict::Deny {
178	        audit_log("deny", cmd, "");
179	        return None;
180	    }
181	    let rewritten = get_rewritten(cmd)?;
182	    audit_log("rewrite", cmd, &rewritten);
183	
184	    let mut modified = args.clone();
185	    if let Some(obj) = modified.as_object_mut() {
186	        obj.insert("command".into(), Value::String(rewritten));
187	    }
188	
189	    // Copilot CLI v1.0.54 only applies `modifiedArgs` when permissionDecision is
190	    // either "allow" or absent. Omitting permissionDecision lets Copilot's normal
191	    // permission flow run on the rewritten command — `rtk *` is not on its
192	    // auto-allow list, so the user sees a prompt for the rewritten command.
193	    let mut response = json!({
194	        "permissionDecisionReason": "RTK auto-rewrite",
195	        "modifiedArgs": modified,
196	    });
197	    if verdict == PermissionVerdict::Allow {
198	        response["permissionDecision"] = json!("allow");
199	    }
200	    Some(response)
201	}
