205	/// Run the Gemini CLI BeforeTool hook.
206	pub fn run_gemini() -> Result<()> {
207	    let input = read_stdin_limited()?;
208	
209	    let json: Value = serde_json::from_str(&input).context("Failed to parse hook input as JSON")?;
210	
211	    let tool_name = json.get("tool_name").and_then(|v| v.as_str()).unwrap_or("");
212	
213	    if tool_name != "run_shell_command" {
214	        print_allow();
215	        return Ok(());
216	    }
217	
218	    let cmd = json
219	        .pointer("/tool_input/command")
220	        .and_then(|v| v.as_str())
221	        .unwrap_or("");
222	
223	    if cmd.is_empty() {
224	        print_allow();
225	        return Ok(());
226	    }
227	
228	    // Check deny rules — Gemini CLI only supports allow/deny (no ask mode).
229	    if permissions::check_command(cmd) == PermissionVerdict::Deny {
230	        let _ = writeln!(
231	            io::stdout(),
232	            r#"{{"decision":"deny","reason":"Blocked by RTK permission rule"}}"#
233	        );
234	        return Ok(());
235	    }
236	
237	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
238	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
239	        .unwrap_or_default();
240	
241	    match rewrite_command(cmd, &excluded, &transparent_prefixes) {
242	        Some(ref rewritten) => {
243	            audit_log("rewrite", cmd, rewritten);
244	            print_rewrite(rewritten);
245	        }
246	        None => print_allow(),
247	    }
248	
249	    Ok(())
250	}
251	
252	fn print_allow() {
253	    let _ = writeln!(io::stdout(), r#"{{"decision":"allow"}}"#);
254	}
255	
256	fn print_rewrite(cmd: &str) {
257	    let output = serde_json::json!({
258	        "decision": "allow",
259	        "hookSpecificOutput": {
260	            "tool_input": {
261	                "command": cmd
262	            }
263	        }
264	    });
265	    let _ = writeln!(io::stdout(), "{}", output);
266	}
