270	/// Best-effort audit log when RTK_HOOK_AUDIT=1.
271	fn audit_log(action: &str, original: &str, rewritten: &str) {
272	    if std::env::var("RTK_HOOK_AUDIT").as_deref() != Ok("1") {
273	        return;
274	    }
275	    let _ = audit_log_inner(action, original, rewritten);
276	}
