278	/// Escape newlines to prevent log-line injection in the pipe-delimited audit log.
279	fn sanitize_log_field(s: &str) -> String {
280	    s.replace('\\', "\\\\")
281	        .replace('|', "\\|")
282	        .replace('\n', "\\n")
283	        .replace('\r', "\\r")
284	}
