286	fn audit_log_inner(action: &str, original: &str, rewritten: &str) -> Option<()> {
287	    let home = dirs::home_dir()?;
288	    let dir = home.join(".local").join("share").join("rtk");
289	    std::fs::create_dir_all(&dir).ok()?;
290	    let path = dir.join("hook-audit.log");
291	    let mut file = std::fs::OpenOptions::new()
292	        .create(true)
293	        .append(true)
294	        .open(path)
295	        .ok()?;
296	    let ts = chrono::Local::now().format("%Y-%m-%dT%H:%M:%S");
297	    writeln!(
298	        file,
299	        "{} | {} | {} | {}",
300	        ts,
301	        action,
302	        sanitize_log_field(original),
303	        sanitize_log_field(rewritten)
304	    )
305	    .ok()
306	}
