308	// ── Claude Code native hook ────────────────────────────────────
309	
310	enum PayloadAction {
311	    Rewrite {
312	        cmd: String,
313	        rewritten: String,
314	        output: Value,
315	    },
316	    Skip {
317	        reason: &'static str,
318	        cmd: String,
319	    },
320	    Ignore,
321	}
322	
323	fn process_claude_payload(v: &Value) -> PayloadAction {
324	    let cmd = match v
325	        .pointer("/tool_input/command")
326	        .and_then(|c| c.as_str())
327	        .filter(|c| !c.is_empty())
328	    {
329	        Some(c) => c,
330	        None => return PayloadAction::Ignore,
331	    };
332	
333	    let verdict = permissions::check_command(cmd);
334	    if verdict == PermissionVerdict::Deny {
335	        return PayloadAction::Skip {
336	            reason: "skip:deny_rule",
337	            cmd: cmd.to_string(),
338	        };
339	    }
340	
341	    let rewritten = match get_rewritten(cmd) {
342	        Some(r) => r,
343	        None => {
344	            return PayloadAction::Skip {
345	                reason: "skip:no_match",
346	                cmd: cmd.to_string(),
347	            }
348	        }
349	    };
350	
351	    let updated_input = {
352	        let mut ti = v.get("tool_input").cloned().unwrap_or_else(|| json!({}));
353	        if let Some(obj) = ti.as_object_mut() {
354	            obj.insert("command".into(), Value::String(rewritten.clone()));
355	        }
356	        ti
357	    };
358	
359	    let mut hook_output = json!({
360	        "hookEventName": PRE_TOOL_USE_KEY,
361	        "permissionDecisionReason": "RTK auto-rewrite",
362	        "updatedInput": updated_input
363	    });
364	
365	    if verdict == PermissionVerdict::Allow {
366	        hook_output
367	            .as_object_mut()
368	            .unwrap()
369	            .insert("permissionDecision".into(), json!("allow"));
370	    }
371	
372	    PayloadAction::Rewrite {
373	        cmd: cmd.to_string(),
374	        rewritten,
375	        output: json!({ "hookSpecificOutput": hook_output }),
376	    }
377	}
