379	/// Run the Claude Code PreToolUse hook natively.
380	pub fn run_claude() -> Result<()> {
381	    let input = read_stdin_limited()?;
382	
383	    let input = input.trim();
384	    if input.is_empty() {
385	        return Ok(());
386	    }
387	
388	    let v: Value = match serde_json::from_str(input) {
389	        Ok(v) => v,
390	        Err(e) => {
391	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
392	            return Ok(());
393	        }
394	    };
395	
396	    match process_claude_payload(&v) {
397	        PayloadAction::Rewrite {
398	            cmd,
399	            rewritten,
400	            output,
401	        } => {
402	            audit_log("rewrite", &cmd, &rewritten);
403	            let _ = writeln!(io::stdout(), "{output}");
404	        }
405	        PayloadAction::Skip { reason, cmd } => {
406	            audit_log(reason, &cmd, "");
407	        }
408	        PayloadAction::Ignore => {}
409	    }
410	
411	    Ok(())
412	}
