423	// ── Cursor native hook ─────────────────────────────────────────
424	
425	/// Cursor on Windows ships hook payloads with one or more leading
426	/// UTF-8 BOMs (`EF BB BF`, sometimes doubled), which serde_json
427	/// refuses to parse. Strip them defensively so the rewrite path keeps
428	/// working instead of silently returning `{}`.
429	fn strip_leading_bom(input: &str) -> &str {
430	    let mut s = input;
431	    while let Some(rest) = s.strip_prefix('\u{feff}') {
432	        s = rest;
433	    }
434	    s
435	}
436	
437	/// Run the Cursor Agent hook natively.
438	pub fn run_cursor() -> Result<()> {
439	    let input = read_stdin_limited()?;
440	
441	    let input = strip_leading_bom(&input).trim();
442	    if input.is_empty() {
443	        let _ = writeln!(io::stdout(), "{{}}");
444	        return Ok(());
445	    }
446	
447	    let v: Value = match serde_json::from_str(input) {
448	        Ok(v) => v,
449	        Err(_) => {
450	            let _ = writeln!(io::stdout(), "{{}}");
451	            return Ok(());
452	        }
453	    };
454	
455	    let cmd = match v
456	        .pointer("/tool_input/command")
457	        .and_then(|c| c.as_str())
458	        .filter(|c| !c.is_empty())
459	    {
460	        Some(c) => c.to_string(),
461	        None => {
462	            let _ = writeln!(io::stdout(), "{{}}");
463	            return Ok(());
464	        }
465	    };
466	
467	    let verdict = permissions::check_command(&cmd);
468	    if verdict == PermissionVerdict::Deny {
469	        audit_log("deny", &cmd, "");
470	        let _ = writeln!(io::stdout(), "{{}}");
471	        return Ok(());
472	    }
473	
474	    let rewritten = match get_rewritten(&cmd) {
475	        Some(r) => r,
476	        None => {
477	            let _ = writeln!(io::stdout(), "{{}}");
478	            return Ok(());
479	        }
480	    };
481	
482	    // Cursor preToolUse currently enforces allow/deny only and can ignore
483	    // updated_input when permission is "ask". Use "allow" for rewritten
484	    // commands unless the command is explicitly denied above.
485	    let decision = "allow";
486	
487	    audit_log("rewrite", &cmd, &rewritten);
488	
489	    // `continue: true` mirrors the shape of every other Cursor hook
490	    // (afterShellExecution, beforeSubmitPrompt, stop, ...). Cursor's
491	    // preToolUse panel renders the JSON it received; without this field
492	    // the panel collapses to `Output: {}` even though the rewrite ran,
493	    // which makes the hook look broken to users.
494	    let output = json!({
495	        "continue": true,
496	        "permission": decision,
497	        "updated_input": { "command": rewritten }
498	    });
499	    let _ = writeln!(io::stdout(), "{output}");
500	    Ok(())
501	}
