530	    let verdict = permissions::check_command_with_rules(&cmd, deny_rules, ask_rules, allow_rules);
531	    if verdict == PermissionVerdict::Deny {
532	        return "{}".to_string();
533	    }
534	
535	    match get_rewritten(&cmd) {
536	        Some(rewritten) => {
537	            let decision = "allow";
538	            let output = json!({
539	                "continue": true,
540	                "permission": decision,
541	                "updated_input": { "command": rewritten }
542	            });
543	            output.to_string()
544	        }
545	        None => "{}".to_string(),
546	    }
547	}
