28	/// Count RTK-covered commands from extracted commands.
29	/// A command is "covered" if it either:
30	/// - starts with "rtk " (explicit rtk invocation), or
31	/// - would be rewritten by the hook (classify_command returns Supported)
32	///
33	/// Chained commands (e.g. "cd ./path && rtk ls") are split so each part
34	/// is classified independently — matching the discover module's behavior.
35	fn count_rtk_commands(cmds: &[ExtractedCommand]) -> (usize, usize, usize) {
36	    let mut total: usize = 0;
37	    let mut rtk: usize = 0;
38	    for c in cmds {
39	        let parts = split_command_chain(&c.command);
40	        for part in &parts {
41	            total += 1;
42	            if part.starts_with("rtk ")
43	                || matches!(classify_command(part), Classification::Supported { .. })
44	            {
45	                rtk += 1;
46	            }
47	        }
48	    }
49	    let output: usize = cmds.iter().filter_map(|c| c.output_len).sum();
50	    (total, rtk, output)
51	}
